"""Blind-10: 50 unseen commands per phase (22 phases incl. browser automation), frozen before being run.

Strict scoring: a command is correct only when the right action is chosen WITH the right details - every string in
`need` must appear in the chosen tool's arguments. Commands that must not act (SAFE / REJECT / CLARIFY / CHAT) are
part of every phase, so acting on them counts against precision.

A(text, tools, *need)   an action: one of `tools` ("a|b"), its arguments containing every `need` string
N(text, outcome)        no action of its own: CHAT / SAFE / REJECT / CLARIFY / MULTI / CONTROL:<intent>
"""
from __future__ import annotations


def A(text: str, tools: str, *need: str) -> dict:
    return {"text": text, "expect": tools, "need": list(need), "kind": "action"}


def N(text: str, outcome: str) -> dict:
    kind = "action" if outcome == "MULTI" or outcome.startswith("CONTROL:") else "none"
    return {"text": text, "expect": outcome, "need": [], "kind": kind}


